SELECT sa.student_id AS studentId, COALESCE(SUM(CASE WHEN q.type = 'essay' THEN 0 ELSE sa.score END), 0) AS objectiveScore, COALESCE(SUM(CASE WHEN q.type = 'essay' THEN sa.score ELSE 0 END), 0) AS subjectiveScore, COALESCE(SUM(sa.score), 0) AS totalScore FROM student_answer sa LEFT JOIN question q ON sa.question_id = q.id WHERE sa.exam_id = #{examId} AND sa.student_id IN
#{sid}
GROUP BY sa.student_id
